SELECT a.Status,a.DocEntry, a.DocNum,a.DocCurr,A.ObjType,a.DocNum,a.doctotal,a.comments, a.doctype,a.CardCode,a.CardName,a.Address  FROM  OPDF a  left outer join PDF4 T0 on T0.[DocNum] =  a.DocEntry   left outer join PDF1 T1 ON a.DocEntry = T1.[DocNum] left outer join oact a1 on a.checkacct=a1.acctcode left outer join oact a2 on a.cashacct=a2.acctcode left outer join nnm1 n on a.series=n.series left outer join pdf2 t2 on t2.docnum=a.DocEntry left outer join opch t3 on  t3.DocEntry = t2.DocEntry left outer join OINV t4 on t2.DocEntry=t4.DocEntry where a.Canceled='N'  and  a.DocTime between cast(Replace(substring(CONVERT(VARCHAR(8), getdate(), 108),1,5),':','') as int)-2 and  cast(Replace(substring(CONVERT(VARCHAR(8), getdate(), 108),1,5),':','') as int) and convert(varchar(10),a.CreateDate ,112)=convert(varchar(10),GETDATE() ,112)
